function solve(l1, l2) {
  const res = [];
  let i = 0, j = 0;
  while (i < l1.length && j < l2.length) {
    if (l1[i] <= l2[j]) res.push(l1[i++]);
    else res.push(l2[j++]);
  }
  return res.concat(l1.slice(i)).concat(l2.slice(j));
}

